class CrmTask { final int? id,customerId; final String title,dueDate,priority,note; final bool completed; const CrmTask({this.id,this.customerId,required this.title,required this.dueDate,this.priority='Bình thường',this.completed=false,this.note=''}); factory CrmTask.fromMap(Map<String,Object?>m)=>CrmTask(id:m['id'] as int?,customerId:m['customer_id'] as int?,title:(m['title']??'') as String,dueDate:(m['due_date']??'') as String,priority:(m['priority']??'Bình thường') as String,completed:((m['completed']??0) as int)==1,note:(m['note']??'') as String); }
